@push('scripts')
<script>
const complaintModal=new bootstrap.Modal('#complaint-modal'),complaintForm=document.getElementById('complaint-form');
function resetComplaint(){complaintForm.reset();complaintForm.action='{{ route('complaints.store') }}';complaintForm.querySelector('.modal-title').textContent='Buat pengaduan';$('#complaint-errors').addClass('d-none').empty()}
function makeComplaintCard(c){const wrap=document.createElement('div');wrap.className='col-12';wrap.id='complaint-'+c.id;const card=document.createElement('article');card.className='card panel p-3 p-lg-4 complaint-card';card.dataset.id=c.id;card.dataset.title=c.title;card.dataset.description=c.description;card.dataset.location=c.location;card.dataset.facility=c.facility_id;card.dataset.status=c.status;const row=document.createElement('div');row.className='d-flex flex-wrap gap-3 align-items-start';if(c.photo_path){const photo=document.createElement('img');photo.className='thumb';photo.alt='Foto bukti';photo.src='/complaints/'+c.id+'/photo';row.append(photo)}const body=document.createElement('div');body.className='flex-grow-1';const heading=document.createElement('div');heading.className='d-flex flex-wrap justify-content-between gap-2';const title=document.createElement('h2');title.className='h5 fw-bold';title.textContent=c.title;const facility=document.createElement('div');facility.className='muted small';facility.textContent=(c.facility?.name||'Fasilitas')+' · '+c.location;const badge=document.createElement('span');badge.className='badge text-bg-warning';badge.textContent=c.status;heading.append(title,badge);const desc=document.createElement('p');desc.className='mt-3';desc.textContent=c.description;const who=document.createElement('div');who.className='small muted';who.textContent='Pelapor: '+(c.user?.name||'');body.append(heading,facility,desc,who);row.append(body);card.append(row);wrap.append(card);return wrap}
$('#add-complaint').on('click',()=>{resetComplaint();complaintModal.show()});
$(document).on('click','.edit-complaint',function(){const card=this.closest('.complaint-card');resetComplaint();complaintForm.action='/complaints/'+card.dataset.id;complaintForm.querySelector('.modal-title').textContent='Ubah pengaduan';for(const key of ['title','description','location','facility_id'])complaintForm.elements.namedItem(key).value=card.dataset[key];complaintModal.show()});
$('#complaint-form').on('submit',async function(e){e.preventDefault();const fd=new FormData(this);if(this.action.includes('/complaints/'))fd.append('_method','PUT');showLoading(true);$('#save-complaint').prop('disabled',true);try{const response=await fetch(this.action,{method:'POST',body:fd,headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}});const data=await response.json();if(!response.ok){$('#complaint-errors').removeClass('d-none').text(data.errors?Object.values(data.errors).flat().join(' '):(data.message||'Gagal menyimpan laporan.'));return}const current=document.getElementById('complaint-'+data.complaint.id);if(current)current.replaceWith(makeComplaintCard(data.complaint));else{$('#empty-complaints').remove();document.getElementById('complaint-list').prepend(makeComplaintCard(data.complaint))}notify(data.message);complaintModal.hide()}catch(error){notify('Koneksi ke server gagal.','danger')}finally{showLoading(false);$('#save-complaint').prop('disabled',false)}});
$(document).on('click','.save-status',async function(){const card=this.closest('.complaint-card'),status=card.querySelector('.status-select').value;showLoading(true);try{const response=await fetch(this.dataset.url,{method:'PATCH',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({status})});const data=await response.json();if(!response.ok)throw Error(data.message||'Status gagal diubah.');card.dataset.status=status;card.querySelector('.badge').textContent=status;card.querySelector('.badge').className='badge text-bg-'+(status==='selesai'?'success':(status==='ditolak'?'danger':'warning'));notify(data.message)}catch(error){notify(error.message,'danger')}finally{showLoading(false)}});
$(document).on('click','.delete-complaint',async function(){if(!confirm('Hapus pengaduan ini?'))return;showLoading(true);try{const response=await fetch(this.dataset.url,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:'_method=DELETE'});const data=await response.json();if(!response.ok)throw Error(data.message);this.closest('[id^=complaint-]').remove();notify(data.message)}catch(error){notify(error.message||'Penghapusan gagal.','danger')}finally{showLoading(false)}});
</script>
@endpush
